// Each block owns ROWS_PER_BLOCK rows; every thread keeps VPT 16-byte vectors
// in registers, so a row is read once and each output written once.
#include <torch/extension.h>
#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

