  for (int k = 0; k < kVpt; ++k) {
    const int64_t off = base + (t + k * kThreadsPerRow) * kVecHalves;
    const uint4 xv = loadVec(reinterpret_cast<const uint4*>(x + off));
    const uint4 rv = loadVec(reinterpret_cast<const uint4*>(residual + off));
