      const float2 b = __half22float2(bh[j]);
      oh[j] = __floats2half2_rn(fmaf((f.x - mean) * rstd, g.x, b.x),
                                fmaf((f.y - mean) * rstd, g.y, b.y));
    }
    storeVec(reinterpret_cast<uint4*>(out + base) + vec, ov);
  }
}

