//
//   added  = fp16(x + residual)                      (materialized boundary)
//   output = (added - mean(added)) * rsqrt(var + eps) * gamma + beta
//
// Each block owns ROWS_PER_BLOCK rows; every thread keeps VPT 16-byte vectors
// in registers, so a row is read once and each output written once.
#include <torch/extension.h>
#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

#include <cstdint>

namespace {

constexpr int kHidden = 1024;                 // problem constant axis H
constexpr int kVecHalves = 8;                 // halves per 16-byte access
constexpr int kVecCount = kHidden / kVecHalves;
constexpr int kVpt = %(vpt)d;                 // 16-byte vectors per thread
constexpr int kThreadsPerRow = kVecCount / kVpt;
constexpr int kRowsPerBlock = %(rpb)d;
constexpr int kBlockThreads = kThreadsPerRow * kRowsPerBlock;
constexpr int kWarpSize = 32;
constexpr int kWarpsPerRow = kThreadsPerRow / kWarpSize;
constexpr int kLanes = kVecHalves / 2;        // half2 pairs inside one vector
constexpr float kEpsilon = 1e-12f;

constexpr unsigned kFullMask = 0xffffffffu;

__device__ __forceinline__ float2 warpSum(float2 v) {
#pragma unroll
  for (int offset = kWarpSize / 2; offset > 0; offset >>= 1) {
    v.x += __shfl_down_sync(kFullMask, v.x, offset);
    v.y += __shfl_down_sync(kFullMask, v.y, offset);
  }
  return v;
}

// Sum {sum, sum of squares} over the warps of one row group; the group's warp 0
// returns the total, other warps return zero.
__device__ __forceinline__ float2 rowSum(float2 v, float2* scratch) {
  const int lane = threadIdx.x & (kWarpSize - 1);
  const int warp = threadIdx.x / kWarpSize;
  const int group = warp / kWarpsPerRow;
  const int wid = warp %% kWarpsPerRow;
  v = warpSum(v);
  if (lane == 0) scratch[group * kWarpsPerRow + wid] = v;
  __syncthreads();
  if (wid "'!= 0) return make_float2(0.f, 0.f);
  v = (lane < kWarpsPerRow) ? scratch[group * kWarpsPerRow + lane]
                            : make_float2(0.f, 0.f);
  return warpSum(v);
}

__device__ __forceinline__ uint4 loadVec(const uint4* p) {
%(load)s
}
__device__ __forceinline__ void storeVec(uint4* p, uint4 v) {
%(store)s
}

__global__ void __launch_bounds__(kBlockThreads) ln_1024_kernel(
    const half* __restrict__ x, const half* __restrict__ residual,
    const half* __restrict__ gamma, const half* __restrict__ beta,
    half* __restrict__ out, half* __restrict__ added) {
  __shared__ float2 scratch[kRowsPerBlock * kWarpsPerRow];
  __shared__ float2 stats[kRowsPerBlock];

  const int group = threadIdx.x / kThreadsPerRow;
  const int t = threadIdx.x %% kThreadsPerRow;
  const int64_t base =
      (static_cast<int64_t>(blockIdx.x) * kRowsPerBlock + group) * kHidden;

  // Pass 1: fp16 residual sum, kept in registers, statistics accumulated in fp32.
  uint4 av[kVpt];
  half2 ah[kVpt * kLanes];
  float2 acc = make_float2(0.f, 0.f);
#pragma unroll
  for (int k = 0; k < kVpt; ++k) {
    const int64_t off = base + (t + k * kThreadsPerRow) * kVecHalves;
    const uint4 xv = loadVec(reinterpret_cast<const uint4*>(x + off));
    const uint4 rv = loadVec(reinterpret_cast<const uint4*>(residual + off));
    const half2* xh = reinterpret_cast<const half2*>(&xv);
    const half2* rh = reinterpret_cast<const half2*>(&rv);
    half2* avh = reinterpret_cast<half2*>(&av[k]);
#pragma unroll
    for (int j = 0; j < kLanes; ++j) {
      ah[k * kLanes + j] = __hadd2(xh[j], rh[j]);
      avh[j] = ah[k * kLanes + j];
      const float2 f = __half22float2(avh[j]);
      acc.x += f.x + f.y;
      acc.y = fmaf(f.x, f.x, acc.y);
      acc.y = fmaf(f.y, f.y, acc.y);
    }
