  }

  const float2 total = rowSum(acc, scratch);
  if (threadIdx.x == 0) {
#pragma unroll
    for (int g = 0; g < kRowsPerBlock; ++g) {
      (void)g;
    }
    const float mean = total.x / kHidden;
    const float var = fmaf(-mean, mean, total.y / kHidden);
    stats[group] = make_float2(mean, rsqrtf(var + kEpsilon));
  }
  __syncthreads();
  const float mean = stats[group].x;
  const float rstd = stats[group].y;

  // Pass 2: affine transform of the register-resident values.
#pragma unroll
  for (int k = 0; k < kVpt; ++k) {
    const int vec = t + k * kThreadsPerRow;
    const uint4 gv = loadVec(reinterpret_cast<const uint4*>(gamma) + vec);
    const uint4 bv = loadVec(reinterpret_cast<const uint4*>(beta) + vec);
    const half2* gh = reinterpret_cast<const half2*>(&gv);
    const half2* bh = reinterpret_cast<const half2*>(&bv);
    uint4 ov;
    half2* oh = reinterpret_cast<half2*>(&ov);
#pragma unroll
    for (int j = 0; j < kLanes; ++j) {
      const float2 f = __half22float2(ah[k * kLanes + j]);
      const float2 g = __half22float2(gh[j]);
      const float2 b = __half22float2(bh[j]);
      oh[j] = __floats2half2_rn(fmaf((f.x - mean) * rstd, g.x, b.x),
